package com.example.paymentservice.dto.response;
import java.math.BigDecimal;
import java.time.LocalDateTime;
public class PaymentResponse { private Long paymentId; private Long bookingId; private BigDecimal amount; private String method; private String status; private String transactionRef; private LocalDateTime paidAt; private LocalDateTime createdAt; private String createdBy; public Long getPaymentId(){return paymentId;} public void setPaymentId(Long v){this.paymentId=v;} public Long getBookingId(){return bookingId;} public void setBookingId(Long v){this.bookingId=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){this.amount=v;} public String getMethod(){return method;} public void setMethod(String v){this.method=v;} public String getStatus(){return status;} public void setStatus(String v){this.status=v;} public String getTransactionRef(){return transactionRef;} public void setTransactionRef(String v){this.transactionRef=v;} public LocalDateTime getPaidAt(){return paidAt;} public void setPaidAt(LocalDateTime v){this.paidAt=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){this.createdAt=v;} public String getCreatedBy(){return createdBy;} public void setCreatedBy(String v){this.createdBy=v;} }